    vcl::PrinterOptionsHelper::UIControlOptions aPageRangeOpt(aPrintContentName, 1, true);
    m_aUIProperties[2].Value = setEditControlOpt(u"pagerange"_ustr, OUString(),
                                                 OUString(), u"PageRange"_ustr,
