    vcl::PrinterOptionsHelper::UIControlOptions aEvenOddOpt(aPrintContentName, 0, true);
    m_aUIProperties[3].Value = setChoiceListControlOpt(u"evenoddbox"_ustr,
                                                        OUString(),
